window.$ = function (selektor) {
    const elementi = document.querySelectorAll(selektor);

    return {
        click: function (funkcija) {
            elementi.forEach(function (element) {
                element.addEventListener("click", funkcija);
            });
            return this;
        },

        slideToggle: function () {
            elementi.forEach(function (element) {
                if (element.style.display === "block") {
                    element.style.display = "none";
                } else {
                    element.style.display = "block";
                }
            });
            return this;
        }
    };
};